def S(img, creatures=(), schools=(), sway=(), smiles=(), waves=(), bubble_from=(), **kw):
    d = dict(creatures=[C[c] for c in creatures], schools=[dict(poly=p, dir=dd, amp=a) for p, dd, a in schools],
             sway=[dict(poly=p, amp=a, **({'root': r} if r is not None else {})) for p, a, r in sway],
             smiles=list(smiles), waves=list(waves), bubble_from=list(bubble_from)); d.update(kw); return d
